<script lang="ts">
  import {searchableSelect} from '#lib/client/searchable-select.ts';
  import {refreshAll} from '$app/navigation';
  import {command,request,display} from '#lib/client/api.ts';
  import type {AppData,Row} from '#lib/client/types.ts';
  import ReferencePicker from './ReferencePicker.svelte';
  import Icon from './Icon.svelte';
  import Status from './Status.svelte';
  let {data,mode}:{data:AppData;mode:'retention'|'holds'|'purposes'}=$props();
  let busy=$state(false),error=$state(''),notice=$state(''),password=$state('');
  let documentKind=$state('document'),years:number|undefined=$state(),basis=$state(''),validFrom=$state(''),responsible=$state(''),source=$state(''),previous=$state('');
  let documentId=$state(''),policyId=$state(''),startedOn=$state(''),assignmentReason=$state(''),assignmentPassword=$state('');
  let holdDocument=$state(''),holdReason=$state(''),reviewDue=$state('');
  let targetKind=$state('document'),targetId=$state(''),purpose=$state(''),legalBasis=$state(''),retainUntil=$state('');
  let ending:Row|null=$state(null),endReason=$state(''),endPassword=$state(''),confirmed=$state(false);
  const policies=$derived((data.related?.retention_policies||[]) as Row[]),holds=$derived((data.related?.legal_holds||[]) as Row[]),purposes=$derived((data.related?.processing_purposes||[]) as Row[]);
  const kinds:Record<string,string>={invoice:'Rechnungsbeleg',contract:'Vertrag',communication:'Korrespondenz',personnel:'Personalunterlage',document:'Allgemeines Dokument'};
  const deviceZone=Intl.DateTimeFormat().resolvedOptions().timeZone;
  function ruleName(row:Row){return `${kinds[row.document_kind]||'Dokument'} · ${row.years} ${Number(row.years)===1?'Jahr':'Jahre'} · gültig ab ${display(row.valid_from,'date')} · ${row.responsible_person||'Verantwortung noch nicht hinterlegt'}`;}
  async function authenticated(secret:string){if(!secret)throw new Error('Bestätigen Sie diesen Schritt mit Ihrer persönlichen Passphrase.');await request('/api/v1/reauth',{password:secret});}
  async function run(action:()=>Promise<void>){if(busy)return;busy=true;error='';notice='';try{await action();await refreshAll().catch(()=>{});}catch(cause){error=cause instanceof Error?cause.message:'Der Schritt konnte nicht gespeichert werden. Ihre Eingaben bleiben erhalten.';}finally{busy=false;}}
  function approveRule(event:SubmitEvent){event.preventDefault();run(async()=>{await authenticated(password);await command('privacy.retention.approve',undefined,{document_kind:documentKind,years:Number(years),basis,valid_from:validFrom,responsible_person:responsible,source_reference:source,...(previous?{previous_version_id:previous}:{})});password='';notice='Die geprüfte Aufbewahrungsregel wurde als eigene freigegebene Version gespeichert.';});}
  function assign(event:SubmitEvent){event.preventDefault();run(async()=>{await authenticated(assignmentPassword);const result=await command('privacy.retention.assign',undefined,{document_id:documentId,policy_id:policyId,started_on:startedOn,reason:assignmentReason});assignmentPassword='';notice=`Die Regel gilt für ${result.assignedVersions??'die ermittelten'} ${Number(result.assignedVersions)===1?'Originalversion':'Originalversionen'}. Aufbewahrung bis ${display(result.retain_until,'date')}.`;});}
  function createHold(event:SubmitEvent){event.preventDefault();run(async()=>{await authenticated(password);await command('privacy.hold.create',undefined,{document_id:holdDocument,reason:holdReason,review_due:reviewDue});password='';holdReason='';notice='Die rechtliche Sperre wurde gespeichert. Sie endet erst durch eine begründete Freigabe.';});}
  function createPurpose(event:SubmitEvent){event.preventDefault();run(async()=>{await authenticated(password);await command('privacy.purpose.create',undefined,{...(targetKind==='document'?{document_id:targetId}:{party_id:targetId}),purpose,legal_basis:legalBasis,...(retainUntil?{retain_until:new Date(retainUntil).toISOString()}:{})});password='';purpose='';legalBasis='';notice='Der konkrete Verarbeitungszweck wurde gespeichert und wird bei einer Entfernung geprüft.';});}
  function startEnding(row:Row){ending=row;endReason='';endPassword='';confirmed=false;error='';notice='';}
  function finish(event:SubmitEvent){event.preventDefault();if(!ending||!confirmed)return;const row=ending;run(async()=>{await authenticated(endPassword);await command(mode==='holds'?'privacy.hold.release':'privacy.purpose.close',row.id,{reason:endReason},row.version);ending=null;endPassword='';notice=mode==='holds'?'Die Sperre wurde mit Begründung aufgehoben. Andere Aufbewahrungspflichten bleiben bestehen.':'Der Zweck wurde nachvollziehbar beendet. Eine Entfernung benötigt weiterhin ihre eigene Prüfung.';});}
</script>
{#if error}<div class="notice error" role="alert"><Icon name="alert"/><div>{error}</div></div>{/if}{#if notice}<div class="notice info" role="status"><Icon name="check"/><div>{notice}</div></div>{/if}
{#if mode==='retention'}
<section class="panel"><header class="panel-header"><div><h2>Bestätigte Aufbewahrungsregeln</h2><p>Eine neue Regelversion ersetzt keine bereits zugeordnete Frist.</p></div></header><div class="panel-body">{#each policies as rule}<details class="privacy-rule"><summary><strong>{ruleName(rule)}</strong><Status value={rule.status}/></summary><dl class="definition-list mt"><div><dt>Verantwortlich</dt><dd>{rule.responsible_person||'Noch nicht bestätigt'}</dd></div><div><dt>Bestätigt am</dt><dd>{display(rule.approved_at,'updated_at')}</dd></div><div class="full"><dt>Fachliche Grundlage</dt><dd>{rule.basis}</dd></div><div class="full"><dt>Nachweis / Quelle</dt><dd>{rule.source_reference}</dd></div></dl></details>{/each}{#if !policies.length}<p class="small">Noch keine bestätigte Aufbewahrungsregel vorhanden. Hinterlegen Sie zuerst die betrieblich geprüfte Frist und ihre Quelle.</p>{/if}</div></section>
<div class="privacy-columns mt"><section class="panel"><header class="panel-header"><div><h2>Eine Regelversion bestätigen</h2><p>Die zuständige Fachperson bestimmt Frist und Anwendungsbereich.</p></div></header><form class="panel-body" onsubmit={approveRule}><fieldset disabled={busy}><div class="field-grid">
<div class="field"><label for="retention-kind">Unterlagenart *</label><select use:searchableSelect={documentKind} id="retention-kind" bind:value={documentKind}>{#each Object.entries(kinds) as [value,label]}<option {value}>{label}</option>{/each}</select></div><div class="field"><label for="retention-years">Bestätigte Aufbewahrung · Jahre *</label><input id="retention-years" type="number" min="1" max="40" step="1" bind:value={years} required/><span class="field-help">Die passende Frist aus dem benannten Nachweis übernehmen. Es gibt keine pauschale Vorgabe für alle Unterlagen.</span></div><div class="field"><label for="retention-valid">Regel gilt ab *</label><input id="retention-valid" type="date" bind:value={validFrom} required/></div><div class="field"><label for="retention-responsible">Verantwortliche Fachperson *</label><input id="retention-responsible" bind:value={responsible} required minlength="3"/></div><div class="field full"><label for="retention-basis">Geprüfte Grundlage und Anwendungsbereich *</label><textarea id="retention-basis" bind:value={basis} required minlength="12" placeholder="Welche Unterlagen umfasst die bestätigte Frist und wodurch ist sie begründet?"></textarea></div><div class="field full"><label for="retention-source">Nachweis oder Quellenreferenz *</label><input id="retention-source" bind:value={source} required minlength="8"/><span class="field-help">Zum Beispiel die Bezeichnung eines geprüften Verfahrensdokuments mit Datum und zuständiger Stelle.</span></div><div class="field full"><label for="retention-previous">Vorgängerversion · optional</label><select use:searchableSelect={previous} id="retention-previous" bind:value={previous}><option value="">Erste Regelversion</option>{#each policies as rule}<option value={rule.id}>{ruleName(rule)}</option>{/each}</select></div><div class="field full"><label for="retention-password">Eigene Passphrase bestätigen *</label><input id="retention-password" type="password" bind:value={password} autocomplete="current-password" required/></div></div><button class="btn primary mt">Regelversion verbindlich bestätigen</button></fieldset></form></section>
<section class="panel"><header class="panel-header"><div><h2>Regel einem Dokument zuordnen</h2><p>Alle ermittelten Originalversionen werden einbezogen.</p></div></header><form class="panel-body" onsubmit={assign}><fieldset disabled={busy}><div class="field mb"><label for="retention-document">Konkretes Dokument *</label><ReferencePicker id="retention-document" bind:value={documentId} reference="documents" initial={data.lookups.documents||[]} required/></div><div class="field mb"><label for="retention-policy">Passende freigegebene Regel *</label><select use:searchableSelect={policyId} id="retention-policy" bind:value={policyId} required><option value="">Regel auswählen</option>{#each policies.filter(row=>row.status==='approved') as rule}<option value={rule.id}>{ruleName(rule)}</option>{/each}</select></div><div class="field mb"><label for="retention-start">Bestätigter Fristbeginn *</label><input id="retention-start" type="date" bind:value={startedOn} required/><span class="field-help">Den für dieses Dokument bestätigten Fristbeginn eintragen. Die Suite berechnet daraus das Ende der zugeordneten Aufbewahrung.</span></div><div class="field mb"><label for="retention-assignment-reason">Anwendbarkeit und Fristbeginn begründen *</label><textarea id="retention-assignment-reason" bind:value={assignmentReason} required minlength="10"></textarea></div><div class="field"><label for="retention-assignment-password">Eigene Passphrase bestätigen *</label><input id="retention-assignment-password" type="password" bind:value={assignmentPassword} autocomplete="current-password" required/></div><button class="btn primary mt" disabled={!policies.length}>Aufbewahrungsfrist zuordnen</button></fieldset></form></section></div>
{:else if mode==='holds'}
<div class="privacy-columns"><section class="panel"><header class="panel-header"><div><h2>Eine rechtliche Sperre setzen</h2><p>Zum Beispiel für eine laufende Klärung oder ein Verfahren.</p></div></header><form class="panel-body" onsubmit={createHold}><fieldset disabled={busy}><div class="field mb"><label for="hold-document">Betroffenes Dokument *</label><ReferencePicker id="hold-document" bind:value={holdDocument} reference="documents" initial={data.lookups.documents||[]} required/></div><div class="field mb"><label for="hold-reason">Konkreter Sperrgrund *</label><textarea id="hold-reason" bind:value={holdReason} required minlength="10"></textarea></div><div class="field mb"><label for="hold-review">Spätestens erneut prüfen am *</label><input id="hold-review" type="date" bind:value={reviewDue} required/><span class="field-help">Dies ist eine Wiedervorlage. Die Sperre läuft an diesem Tag nicht automatisch ab.</span></div><div class="field"><label for="hold-password">Eigene Passphrase bestätigen *</label><input id="hold-password" type="password" bind:value={password} autocomplete="current-password" required/></div><button class="btn primary mt">Dokument rechtlich sperren</button></fieldset></form></section><section class="panel"><header class="panel-header"><h2>Gespeicherte Sperren</h2></header><div class="panel-body">{#each holds as row}<article class="privacy-row"><div><h3>{row.document_name||'Berechtigtes Dokument'}</h3><Status value={row.status}/></div><p>{row.reason}</p><p class="field-help">Erneut prüfen am {display(row.review_due,'date')}</p>{#if row.released_at}<p class="field-help">Aufgehoben {display(row.released_at,'updated_at')} · {row.release_reason}</p>{:else}<button class="btn small mt" disabled={busy} onclick={()=>startEnding(row)}>Aufhebung begründet prüfen</button>{/if}</article>{/each}{#if !holds.length}<p class="small">Noch keine rechtlichen Sperren im berechtigten Bestand hinterlegt.</p>{/if}</div></section></div>
{:else}
<div class="privacy-columns"><section class="panel"><header class="panel-header"><div><h2>Verarbeitungszweck dokumentieren</h2><p>Den tatsächlichen Zweck und seine geprüfte Grundlage benennen.</p></div></header><form class="panel-body" onsubmit={createPurpose}><fieldset disabled={busy}><div class="field mb"><label for="purpose-kind">Der Zweck bezieht sich auf *</label><select use:searchableSelect={targetKind} id="purpose-kind" bind:value={targetKind} onchange={()=>targetId=''}><option value="document">Ein konkretes Dokument</option><option value="party">Ein Geschäftspartnerprofil</option></select></div><div class="field mb"><label for="purpose-target">{targetKind==='document'?'Dokument':'Geschäftspartner'} *</label>{#key targetKind}<ReferencePicker id="purpose-target" bind:value={targetId} reference={targetKind==='document'?'documents':'parties'} initial={data.lookups[targetKind==='document'?'documents':'parties']||[]} required/>{/key}</div><div class="field mb"><label for="purpose-text">Konkreter Verarbeitungszweck *</label><textarea id="purpose-text" bind:value={purpose} required minlength="5" placeholder="Wofür wird diese konkrete Unterlage oder dieses Profil noch benötigt?"></textarea></div><div class="field mb"><label for="purpose-basis">Geprüfte Rechts- oder Vertragsgrundlage *</label><textarea id="purpose-basis" bind:value={legalBasis} required minlength="5"></textarea></div><div class="field mb"><label for="purpose-until">Bestätigtes Zweckende · optional</label><input id="purpose-until" type="datetime-local" bind:value={retainUntil}/><span class="field-help">Leer bedeutet: Der Zweck bleibt bis zum begründeten Abschluss aktiv. Zeiteingabe in Ihrer Gerätezeitzone {deviceZone}.</span></div><div class="field"><label for="purpose-password">Eigene Passphrase bestätigen *</label><input id="purpose-password" type="password" bind:value={password} autocomplete="current-password" required/></div><button class="btn primary mt">Zweck dokumentieren</button></fieldset></form></section><section class="panel"><header class="panel-header"><h2>Gespeicherte Zwecke</h2></header><div class="panel-body">{#each purposes as row}<article class="privacy-row"><div><h3>{row.document_name||row.party_name||'Berechtigtes Objekt'}</h3><Status value={row.status}/></div><p>{row.purpose}</p><p class="field-help">Grundlage: {row.legal_basis}</p>{#if row.retain_until}<p class="field-help">Bestätigtes Zweckende {display(row.retain_until,'updated_at')}</p>{/if}{#if row.closed_at}<p class="field-help">Beendet {display(row.closed_at,'updated_at')} · {row.closure_reason}</p>{:else}<button class="btn small mt" disabled={busy} onclick={()=>startEnding(row)}>Zweck begründet beenden</button>{/if}</article>{/each}{#if !purposes.length}<p class="small">Noch keine gesonderten Zwecke hinterlegt. Aufbewahrungsregeln und rechtliche Sperren werden unabhängig davon geprüft.</p>{/if}</div></section></div>
{/if}
{#if ending}<section class="panel mt"><header class="panel-header"><h2>{mode==='holds'?'Rechtliche Sperre aufheben':'Konkreten Zweck beenden'}</h2></header><form class="panel-body" onsubmit={finish}><fieldset disabled={busy}><div class="action-preview"><h3>{ending.document_name||ending.party_name||'Berechtigtes Objekt'}</h3><p class="small mt">{mode==='holds'?ending.reason:ending.purpose}</p></div><div class="field mb"><label for="privacy-end-reason">Geprüfter Abschlussgrund *</label><textarea id="privacy-end-reason" bind:value={endReason} required minlength="10"></textarea></div><label class="check-field mb"><input type="checkbox" bind:checked={confirmed} required/><span>{mode==='holds'?'Die zuständige Person hat die Aufhebung dieser konkreten Sperre geprüft.':'Der benannte Zweck ist tatsächlich beendet und der Abschluss wurde geprüft.'} Andere Fristen und Sperren werden weiterhin gesondert berücksichtigt.</span></label><div class="field"><label for="privacy-end-password">Eigene Passphrase bestätigen *</label><input id="privacy-end-password" type="password" bind:value={endPassword} autocomplete="current-password" required/></div><div class="inline-actions mt"><button class="btn" type="button" onclick={()=>ending=null}>Zurück</button><button class="btn primary" disabled={!confirmed}>Begründeten Abschluss bestätigen</button></div></fieldset></form></section>{/if}
<style>fieldset{border:0;padding:0;margin:0;min-width:0}.privacy-columns{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;align-items:start}.privacy-columns .field-grid{grid-template-columns:1fr}.privacy-rule+.privacy-rule{border-top:1px solid var(--line);padding-top:20px;margin-top:20px}.privacy-rule summary{display:flex;align-items:center;justify-content:space-between;gap:15px;cursor:pointer;min-height:42px}.privacy-rule strong{font-size:13px;font-weight:500}.privacy-row+.privacy-row{border-top:1px solid var(--line);padding-top:22px;margin-top:22px}.privacy-row>div{display:flex;justify-content:space-between;gap:15px;align-items:start}.privacy-row h3{font-size:14px;font-weight:550;overflow-wrap:anywhere}.privacy-row>p{font-size:13px;margin-top:10px;overflow-wrap:anywhere}@media(max-width:1100px){.privacy-columns{grid-template-columns:1fr}}@media(max-width:760px){.privacy-rule summary{flex-direction:column;align-items:start;gap:9px}.privacy-rule strong{font-size:14px}.privacy-row>p{font-size:14px}}</style>
